import { Component, Element, Host, Prop, State, h } from "@stencil/core";

/** Variant preset configuration */
type VariantPreset = {
	rounded: boolean;
	align: "start" | "end";
	raised: boolean;
	sticky: boolean;
};

const VARIANT_PRESETS: Record<string, VariantPreset> = {
	"body-content": { rounded: true, align: "start", raised: true, sticky: true },
	drawer: { rounded: false, align: "end", raised: false, sticky: true },
};

/**
 * Action button container for page footers, drawers, and modals.
 *
 * Supports sticky positioning with automatic stuck detection - adds visual
 * feedback (shadow, rounded corners) when the bar overlaps scrolled content.
 *
 * Use semantic variants for common contexts, or individual props for custom behavior.
 *
 * @since 2.18.10
 * @status experimental
 *
 * @slot - Action buttons (hbr-button elements).
 *
 * @example
 * // Page content (left-aligned, rounded when stuck)
 * <hbr-sticky-action-bar variant="body-content">
 *   <hbr-button variant="text">Cancel</hbr-button>
 *   <hbr-button>Save</hbr-button>
 * </hbr-sticky-action-bar>
 *
 * @example
 * // Drawer/modal (right-aligned, no rounded corners)
 * <hbr-sticky-action-bar variant="drawer">
 *   <hbr-button variant="text">Cancel</hbr-button>
 *   <hbr-button>Confirm</hbr-button>
 * </hbr-sticky-action-bar>
 */
@Component({
	tag: "hbr-sticky-action-bar",
	styleUrl: "sticky-action-bar.scss",
	scoped: false,
})
export class StickyActionBar {
	@Element() el: HTMLElement;

	/**
	 * Context-aware preset: 'body-content' (footer for inline forms in page content) or 'drawer' (drawer/modal).
	 * Overrides individual props when set.
	 */
	@Prop({ reflect: true }) variant: "body-content" | "drawer";

	/** Button spacing: 'md' (8px), 'sm' (4px compact). Default: md. */
	@Prop() size: "md" | "sm" = "md";

	/** Button alignment: 'start' (left) or 'end' (right). */
	@Prop() align: "start" | "end" = "start";

	/** Shows shadow when stuck and overlapping content. */
	@Prop() raised = false;

	/** Rounded top corners when stuck (use for page content, not drawers). */
	@Prop() rounded = false;

	/** Enables sticky positioning at container bottom. */
	@Prop() sticky = false;

	/** Internal state: true when bar is stuck (scrolled, overlapping content) */
	@State() isStuck = false;

	private sentinel: HTMLElement;
	private observer: IntersectionObserver;

	/** Resolves effective prop value, preferring variant preset if variant is set */
	private getEffective<K extends keyof VariantPreset>(
		prop: K,
	): VariantPreset[K] {
		if (this.variant && VARIANT_PRESETS[this.variant]) {
			return VARIANT_PRESETS[this.variant][prop];
		}
		return this[prop] as VariantPreset[K];
	}

	componentDidLoad() {
		if (this.getEffective("sticky")) {
			this.setupStickyDetection();
		}
	}

	disconnectedCallback() {
		this.cleanupStickyDetection();
	}

	componentWillRender() {
		// Apply effective values as attributes for CSS styling
		this.el.setAttribute("size", this.size);
		this.el.setAttribute("align", this.getEffective("align"));

		// Reflect effective boolean props
		const effectiveRaised = this.getEffective("raised");
		const effectiveRounded = this.getEffective("rounded");
		const effectiveSticky = this.getEffective("sticky");

		if (effectiveRaised) {
			this.el.setAttribute("raised", "");
		} else {
			this.el.removeAttribute("raised");
		}

		if (effectiveRounded) {
			this.el.setAttribute("rounded", "");
		} else {
			this.el.removeAttribute("rounded");
		}

		if (effectiveSticky) {
			this.el.setAttribute("sticky", "");
		} else {
			this.el.removeAttribute("sticky");
		}
	}

	/**
	 * Stuck detection:
	 * Sets up IntersectionObserver with a sentinel element to detect stuck state.
	 * When the sentinel (placed after the sticky bar) goes out of view,
	 * it means the bar is stuck/overlapping content.
	 */
	private setupStickyDetection() {
		// Create sentinel element - a 1px element placed after the sticky bar
		this.sentinel = document.createElement("div");
		this.sentinel.className = "hbr-sticky-action-bar-sentinel";
		this.sentinel.setAttribute("aria-hidden", "true");
		this.el.insertAdjacentElement("afterend", this.sentinel);

		// Find scroll container for the observer root
		const scrollContainer = this.findScrollContainer();

		this.observer = new IntersectionObserver(
			(entries) => {
				// Sentinel visible = bar is resting (not stuck)
				// Sentinel hidden = bar is stuck (overlapping content)
				const isIntersecting = entries[0]?.isIntersecting ?? true;
				this.isStuck = !isIntersecting;
			},
			{
				root: scrollContainer,
				threshold: 0,
				// Small margin to trigger slightly before sentinel is fully hidden
				rootMargin: "0px 0px 1px 0px",
			},
		);

		this.observer.observe(this.sentinel);
	}

	private cleanupStickyDetection() {
		this.observer?.disconnect();
		this.sentinel?.remove();
	}

	/**
	 * Traverses up the DOM to find the nearest scrollable container.
	 * Returns null to use viewport if none found.
	 */
	private findScrollContainer(): Element | null {
		let parent = this.el.parentElement;
		while (parent) {
			const style = getComputedStyle(parent);
			const overflowY = style.overflowY;
			if (overflowY === "auto" || overflowY === "scroll") {
				return parent;
			}
			parent = parent.parentElement;
		}
		return null; // Use viewport
	}

	render() {
		const effectiveSticky = this.getEffective("sticky");
		return <Host class={{ "is-stuck": this.isStuck && effectiveSticky }} />;
	}
}
